  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["PH-H5966"] = {"id":"PH-H5966","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7483_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将保和省Talibon市镇Carlos P. Garcia总统省立医院床位由75张增至100张，将该院迁至保和省Talibon San Jose，并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Pres. Carlos P. Garcia Provincial Hospital in the Municipality of Talibon, Province of Bohol, From Seventy-five (75) To One Hundred (100) Beds, and Relocating the Said Hospital in San Jose, Talibon, Bohol, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Pres. Carlos P. Garcia Provincial Hospital in the Municipality of Talibon, Province of Bohol, From Seventy-five (75) To One Hundred (100) Beds, and Relocating the Said Hospital in San Jose, Talibon, Bohol, and Appropriating Funds Therefor","vi":"Đạo luật tăng sức chứa giường bệnh của Bệnh viện Tỉnh Pres. Carlos P. Garcia tại Đô thị Talibon, Tỉnh Bohol từ 75 lên 100 giường, và phân bổ kinh phí","th":"พระราชบัญญัติเพิ่มจำนวนเตียงของโรงพยาบาลจังหวัด Pres. Carlos P. Garcia ในเทศบาล Talibon จังหวัด Bohol จาก 75 เป็น 100 เตียง และจัดสรรงบประมาณ","id":"Undang-Undang meningkatkan kapasitas tempat tidur Rumah Sakit Provinsi Pres. Carlos P. Garcia di Kotamadya Talibon, Provinsi Bohol dari 75 menjadi 100 tempat tidur, dan mengalokasikan dana","ms":"Akta meningkatkan kapasiti katil Hospital Wilayah Pres. Carlos P. Garcia di Perbandaran Talibon, Wilayah Bohol daripada 75 kepada 100 katil, serta memperuntukkan dana"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7483","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7483_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5966-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Pres. Carlos P. Garcia Provincial Hospital in the Municipality of Talibon, Province of Bohol, is hereby increased from seventy-five (75) to one hundred (100) beds, and relocating the said hospital in San Jose, Talibon, Bohol."}},{"id":"PH-H5966-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5966-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Pres. Carlos P. Garcia Provincial Hospital in the Municipality of Talibon, Province of Bohol, From Seventy-five (75) To One Hundred (100) Beds, and Relocating the Said Hospital in San Jose, Talibon, Bohol, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5967"] = {"id":"PH-H5967","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7484_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Abulog市","en":"An Act Converting the Rural Health Unit in the Municipality of Abulog, Province of Cagayan, Into A Five-bed Capacity Health Infirmary, To Be Known As the Abulog Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit in the Municipality of Abulog, Province of Cagayan, Into A Five-bed Capacity Health Infirmary, To Be Known As the Abulog Health Infirmary, and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Trạm Y tế Nông thôn tại Đô thị Abulog, Tỉnh Cagayan thành Bệnh xá Abulog, và phân bổ kinh phí","th":"พระราชบัญญัติเปลี่ยนสถานะสถานีอนามัยชนบทในเทศบาล Abulog จังหวัด Cagayan เป็นสถานีอนามัย Abulog และจัดสรรงบประมาณ","id":"Undang-Undang mengubah status Unit Kesehatan Pedesaan di Kotamadya Abulog, Provinsi Cagayan menjadi Infirmari Kesehatan Abulog, dan mengalokasikan dana","ms":"Akta menukar status Unit Kesihatan Luar Bandar di Perbandaran Abulog, Wilayah Cagayan kepada Infirmari Kesihatan Abulog, dan memperuntukkan dana"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7484","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7484_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5967-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The rural health unit in the Municipality of Abulog, Province of Cagayan, is hereby converted into a five-bed capacity health infirmary, to be known as the Abulog Health Infirmary."}},{"id":"PH-H5967-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5967-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85"};
  FT["PH-H5968"] = {"id":"PH-H5968","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7485_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Filipinas 广播协会公司在米沙鄢与棉兰老为商业目的建设、运营和维护无线电广播与电视站并为其他目的法案","en":"An Act Granting Filipinas Broadcasting Association, Inc. A Franchise To Construct, Operate and Maintain For Commercial Purposes Radio Broadcasting and Television Stations in the Visayas and Mindanao and For Other Purposes","orig":"An Act Granting Filipinas Broadcasting Association, Inc. A Franchise To Construct, Operate and Maintain For Commercial Purposes Radio Broadcasting and Television Stations in the Visayas and Mindanao and For Other Purposes","vi":"Đạo luật cấp quyền khai thác cho Filipinas Broadcasting Association, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Filipinas Broadcasting Association, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Filipinas Broadcasting Association, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Filipinas Broadcasting Association, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7485","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7485_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5968-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Filipinas Broadcasting Association, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, operate and maintain for commercial purposes and in the public interest radio broadcasting and television stations in the Visayas and Mindanao with the corresponding technological auxiliaries or facilities, special broadcast and other program, distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5968-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operations of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunications services grantees without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5968-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5968-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5968-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5968-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5968-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. The grantee shall construct, complete and operate a television or radio station within two (2) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5968-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5968-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H5968-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5968-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5968-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5968-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5968-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5968-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Republic of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5968-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Filipinas Broadcasting Association, Inc. A Franchise To Construct, Operate and Maintain For Commercial Purposes Radio Broadcasting and Television Stations in the Visayas and Mindanao and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5969"] = {"id":"PH-H5969","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7486_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Batuan市","en":"An Act Establishing A High School in Barangay Poblacion, Municipality of Batuan, Province of Bohol, To Be Known As the Batuan High School, and Appropriating Funds Therefor","orig":"An Act Establishing A High School in Barangay Poblacion, Municipality of Batuan, Province of Bohol, To Be Known As the Batuan High School, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông tại Barangay Poblacion, Thị trấn Batuan, Tỉnh Bohol được biết đến với tên gọi Trường trung học phổ thông Batuan","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาในบารังไกย์ Poblacion, เทศบาล Batuan, จังหวัด Bohol ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษา Batuan","id":"Undang-Undang mendirikan Sekolah Menengah Atas di Barangay Poblacion, Kotamadya Batuan, Provinsi Bohol dikenal sebagai Sekolah Menengah Atas Batuan","ms":"Akta menubuhkan Sekolah Menengah di Barangay Poblacion, Perbandaran Batuan, Wilayah Bohol dikenali sebagai Sekolah Menengah Batuan"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7486","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7486_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5969-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in Barangay Poblacion, Municipality of Batuan, Province of Bohol, to be known as the Batuan High School."}},{"id":"PH-H5969-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5969-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5969-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85"};
  FT["PH-H5970"] = {"id":"PH-H5970","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7487_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将吉马拉斯区医院现有25张床位改扩建为75张床位并为此拨款的法案","en":"An Act Converting the Guimaras District Hospital From Its Present Twenty-five-bed Capacity Into A Seventy-five-bed Capacity and Appropriating Funds Therefor","orig":"An Act Converting the Guimaras District Hospital From Its Present Twenty-five-bed Capacity Into A Seventy-five-bed Capacity and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7487","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7487_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5970-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Department of Health shall cause the conversion of the existing Guimaras District Hospital from its present twenty-five-bed capacity into a seventy-five-bed capacity hospital."}},{"id":"PH-H5970-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriation Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5970-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Guimaras District Hospital From Its Present Twenty-five-bed Capacity Into A Seventy-five-bed Capacity and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
