  FT["PH-H5989"] = {"id":"PH-H5989","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7506_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Cabagan市","en":"An Act Establishing A High School in the Municipality of Cabagan, Province of Isabela, To Be Known As the Delfin Albano High School, and Appropriating Funds Therefor","orig":"An Act Establishing A High School in the Municipality of Cabagan, Province of Isabela, To Be Known As the Delfin Albano High School, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông tại Thị trấn Cabagan, Tỉnh Isabela được biết đến với tên gọi Trường trung học phổ thông Delfin Albano","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาในเทศบาล Cabagan, จังหวัด Isabela ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษา Delfin Albano","id":"Undang-Undang mendirikan Sekolah Menengah Atas di Kotamadya Cabagan, Provinsi Isabela dikenal sebagai Sekolah Menengah Atas Delfin Albano","ms":"Akta menubuhkan Sekolah Menengah di Perbandaran Cabagan, Wilayah Isabela dikenali sebagai Sekolah Menengah Delfin Albano"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7506","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7506_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5989-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Cabagan, Province of Isabela, to be known as the Delfin Albano High School."}},{"id":"PH-H5989-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5989-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5989-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 18, 1992."}}],"pack":"ph-p85"};
  FT["PH-H5990"] = {"id":"PH-H5990","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7507_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Anahawan市","en":"An Act Establishing A Vocational High School in the Municipality of Anahawan, Province of Southern Leyte, To Be Known As the Anahawan Vocational High School, and Appropriating Funds Therefor","orig":"An Act Establishing A Vocational High School in the Municipality of Anahawan, Province of Southern Leyte, To Be Known As the Anahawan Vocational High School, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường Trung học Dạy nghề Anahawan tại Đô thị Anahawan, Tỉnh Southern Leyte, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาอาชีวศึกษา Anahawan ในเทศบาล Anahawan จังหวัด Southern Leyte และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Menengah Kejuruan Anahawan di Kotamadya Anahawan, Provinsi Southern Leyte, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Sekolah Menengah Vokasional Anahawan di Perbandaran Anahawan, Wilayah Southern Leyte, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7507","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7507_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5990-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a vocational high school in the Municipality of Anahawan, Province of Southern Leyte, to be known as the Anahawan Vocational High School."}},{"id":"PH-H5990-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5990-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5990-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85"};
