  FT["PH-H6010"] = {"id":"PH-H6010","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7527_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Gerona市","en":"An Act Converting the Rural Health Unit I in the Municipality of Gerona, Province of Tarlac, Into A Five-bed Capacity Health Infirmary, To Be Known As the Gerona Health Infirmary, and Appropriating Funds Therefor","orig":"An Act Converting the Rural Health Unit I in the Municipality of Gerona, Province of Tarlac, Into A Five-bed Capacity Health Infirmary, To Be Known As the Gerona Health Infirmary, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7527","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7527_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6010-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Rural Health Unit I in the Municipality of Gerona, Province of Tarlac, is hereby converted into a five-bed capacity health infirmary, to be known as the Gerona Health Infirmary."}},{"id":"PH-H6010-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6010-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85"};
  FT["PH-H6011"] = {"id":"PH-H6011","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7528_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将宿务市南部 Islands 医疗中心的名称变更为Vicente Sotto 纪念医疗中心的法案","en":"An Act Changing the Name of the Southern Islands Medical Center in the City of Cebu To Vicente Sotto Memorial Medical Center","orig":"An Act Changing the Name of the Southern Islands Medical Center in the City of Cebu To Vicente Sotto Memorial Medical Center","vi":"Đạo luật đổi tên Trung tâm y tế Southern Islands tại Thành phố Cebu thành Trung tâm y tế Vicente Sotto Memorial","th":"พระราชบัญญัติเปลี่ยนชื่อศูนย์การแพทย์ Southern Islands ในเมือง Cebu เป็นศูนย์การแพทย์ Vicente Sotto Memorial","id":"Undang-Undang mengubah nama Pusat Medis Southern Islands di Kota Cebu menjadi Pusat Medis Vicente Sotto Memorial","ms":"Akta menukar nama Pusat Perubatan Southern Islands di Bandaraya Cebu menjadi Pusat Perubatan Vicente Sotto Memorial"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7528","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7528_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6011-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Southern Islands Medical Center in the City of Cebu is hereby changed to Vicente Sotto Memorial Medical Center."}},{"id":"PH-H6011-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Southern Islands Medical Center in the City of Cebu To Vicente Sotto Memorial Medical Center","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6012"] = {"id":"PH-H6012","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7529_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Vanguard 广播网络公司在吕宋岛建设、安装、运营和维护广播电视站并为其他目的法案","en":"An Act Granting Vanguard Radio Network Company, Inc. A Franchise To Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations in the Island of Luzon and For Other Purposes","orig":"An Act Granting Vanguard Radio Network Company, Inc. A Franchise To Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations in the Island of Luzon and For Other Purposes","vi":"Đạo luật cấp quyền khai thác cho Vanguard Radio Network Company, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Vanguard Radio Network Company, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Vanguard Radio Network Company, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Vanguard Radio Network Company, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7529","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7529_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6012-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scopeof Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Vanguard Radio Network Company, Inc., its successors or assigns, hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio and television broadcasting stations in the island of Luzon with the corresponding auxiliary, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6012-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6012-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission."}},{"id":"PH-H6012-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6012-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right to Government. – A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6012-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from tile date of effectivity of this Act unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6012-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6012-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Public Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stock within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6012-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property exclusive of this franchise as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof - Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6012-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Government – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6012-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6012-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6012-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6012-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing and Non-exclusivity Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6012-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"General Broadcast Policy. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6012-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Vanguard Radio Network Company, Inc. A Franchise To Construct, Install, Operate and Maintain Radio and Television Broadcasting Stations in the Island of Luzon and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6013"] = {"id":"PH-H6013","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7530_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"将依第 5172 号共和国法授予菲律宾天主教主教团（原天主教福利组织）在菲律宾运营广播电视站的特许经营权自 1992 年 8 月 4 日起再延长二十五年的法案","en":"An Act Extending the Franchise Granted To the Catholic Bishops'conference of the Philippines, Inc., (Formerly the Catholic Welfare Organization) To Construct, Operate and Maintain Radio Broadcasting and Television Stations in the Philippines Under Republic Act Numbered Fifty-one Hundred and Seventy-two To Another Twenty-five (25) Years From August 4, 1992 and For Other Purposes","orig":"An Act Extending the Franchise Granted To the Catholic Bishops'conference of the Philippines, Inc., (Formerly the Catholic Welfare Organization) To Construct, Operate and Maintain Radio Broadcasting and Television Stations in the Philippines Under Republic Act Numbered Fifty-one Hundred and Seventy-two To Another Twenty-five (25) Years From August 4, 1992 and For Other Purposes","vi":"Đạo luật gia hạn thêm 25 năm đặc quyền của Catholic Bishops'conference of the Philippines, Inc.","th":"พระราชบัญญัติขยายสัมปทานของ Catholic Bishops'conference of the Philippines, Inc. ออกไปอีก 25 ปี","id":"Undang-Undang memperpanjang konsesi milik Catholic Bishops'conference of the Philippines, Inc. selama 25 tahun lagi","ms":"Akta melanjutkan konsesi milik Catholic Bishops'conference of the Philippines, Inc. selama 25 tahun lagi"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7530","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7530_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6013-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Extension of the Franchise. – The life of the franchise of the Catholic Bishops' Conference of the Philippines, Inc., (formerly the Catholic Welfare Organization) to construct, operate and maintain radio broadcasting and television stations in the Philippines under Republic Act No. 5172 is hereby extended to another twenty-five (25) years from August 4, 1992."}},{"id":"PH-H6013-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Incorporation of Other Provisions of Republic Act No. 5172. – All other provisions, terms and conditions contained in Republic Act No. 5172 which are still in force and are not affected by this Act are hereby made integral parts of this Act."}},{"id":"PH-H6013-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Parity Clause. – In the event any competing individual, partnership or corporation has received or shall receive from the Congress of the Philippines a similar franchise containing any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H6013-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6013-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6013-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Responsibility to the Public. – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, or speech, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6013-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6013-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage *shall be in lieu of all taxes on this franchise or earnings thereof. Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6013-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership. – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H6013-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6013-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6013-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H6013-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause . – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6013-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause . – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6013-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6013-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Franchise Granted To the Catholic Bishops'conference of the Philippines, Inc., (Formerly the Catholic Welfare Organization) To Construct, Operate and Maintain Radio Broadcasting and Television Stations in the Philippines Under Republic Act Numbered Fifty-one Hundred and Seventy-two To Another Twenty-five (25) Years From August 4, 1992 and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6014"] = {"id":"PH-H6014","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7531_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将拉乌尼翁省Balaoan市镇北拉乌尼翁妇产与儿童医院床位由25张增至50张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Northern La Union Maternity and Children's Hospital in the Municipality of Balaoan, Province of La Union, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Northern La Union Maternity and Children's Hospital in the Municipality of Balaoan, Province of La Union, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor","vi":"Đạo luật tăng số giường bệnh của Northern La Union Maternity and Children's Hospital tại Thị trấn Balaoan, Tỉnh La Union từ hai mươi lăm lên năm mươi giường","th":"พระราชบัญญัติเพิ่มจำนวนเตียงของ Northern La Union Maternity and Children's Hospital ในเทศบาล Balaoan, จังหวัด La Union จากยี่สิบห้าเป็นห้าสิบเตียง","id":"Undang-Undang menambah kapasitas tempat tidur dari Northern La Union Maternity and Children's Hospital di Kotamadya Balaoan, Provinsi La Union dari dua puluh lima menjadi lima puluh tempat tidur","ms":"Akta menambah kapasiti katil daripada Northern La Union Maternity and Children's Hospital di Perbandaran Balaoan, Wilayah La Union daripada dua puluh lima kepada lima puluh katil"},"level":"law","status":"active","topics":["labor","civil","health"],"docNumber":"Republic Act No. 7531","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7531_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6014-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Northern La Union Maternity and Children's Hospital in the Municipality of Balaoan, Province of La Union, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H6014-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6014-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Northern La Union Maternity and Children's Hospital in the Municipality of Balaoan, Province of La Union, From Twenty-five (25) To Fifty (50) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
