  FT["PH-H6031"] = {"id":"PH-H6031","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7548_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将阿克兰省Malay市镇Balusbus描笼涯Malay市镇医院由10张床位的市镇医院扩建升级为25张床位的区医院，名称为Malay区医院，并为此拨款","en":"An Act Expanding and Upgrading the Malay Municipal Hospital in Barangay Balusbus, Municipality of Malay, Province of Aklan, From A Ten-bed Capacity Municipal Hospital To A Twenty-five-bed Capacity District Hospital, To Be Known As the Malay District Hospital, and Appropriating Funds Therefor","orig":"An Act Expanding and Upgrading the Malay Municipal Hospital in Barangay Balusbus, Municipality of Malay, Province of Aklan, From A Ten-bed Capacity Municipal Hospital To A Twenty-five-bed Capacity District Hospital, To Be Known As the Malay District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","health"],"docNumber":"Republic Act No. 7548","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7548_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6031-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Malay Municipal Hospital in Barangay Balusbus, Municipality of Malay, Province of Aklan, is hereby expanded and upgraded from a ten-bed capacity municipal hospital to a twenty-five-bed capacity district hospital, to be known as the Malay District Hospital."}},{"id":"PH-H6031-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6031-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Expanding and Upgrading the Malay Municipal Hospital in Barangay Balusbus, Municipality of Malay, Province of Aklan, From A Ten-bed Capacity Municipal Hospital To A Twenty-five-bed Capacity District Hospital, To Be Known As the Malay District Hospital, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6032"] = {"id":"PH-H6032","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7549_1992.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"免除本地与国际体育赛事所得全部奖品与奖金缴纳所得税及其他形式税收并为其他目的法案","en":"An Act Exempting All Prizes and Awards Gained From Local and International Sports Tournaments and Competitions From the Payment of Income and Other Forms of Taxes and For Other Purposes","orig":"An Act Exempting All Prizes and Awards Gained From Local and International Sports Tournaments and Competitions From the Payment of Income and Other Forms of Taxes and For Other Purposes"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 7549","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7549_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6032-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"All prizes and awards granted to athletes in local and international sports tournaments and competitions held in the Philippines or abroad and sanctioned by their respective national sports associations shall be exempt from income tax: Provided, That such prizes and awards given to said athletes shall be deductible in full from the gross income of the donor: Provided, further, That the donors of said prizes and awards shall be exempt from the payment of donor's tax.\nThe benefits herein provided shall cover the XVIth Southeast Asian Games (SEA Games) held in Manila from November 25 to December 5, 1991."}},{"id":"PH-H6032-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"As used in this Act, the term:\n1. \"Sports tournaments and competitions\" shall mean those tournaments and competitions sanctioned by the national sports associations in accordance with the rules and regulations pursuant to Section 3 hereof; and\n2. \"National sports association\" shall mean those duly accredited by the Philippine Olympic Committee."}},{"id":"PH-H6032-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon the recommendation of the Commissioner of the Bureau of Internal Revenue, the Philippine Sports Commission (PSC) and the Department of Finance shall, within thirty (30) days from the effectivity of this Act, jointly promulgate rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H6032-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All laws, decrees, executive orders, other executive issuances, rules and regulations, or parts thereof, which are inconsistent with this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H6032-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon the completion of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Exempting All Prizes and Awards Gained From Local and International Sports Tournaments and Competitions From the Payment of Income and Other Forms of Taxes and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6033"] = {"id":"PH-H6033","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7550_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布每年2月16日为卡洛奥坎市日、即马尼拉大都会卡洛奥坎市特别非工作日假日的法案","en":"An Act Declaring February 16 of Every Year As Caloocan City Day, A Special Nonworking Holiday in Caloocan City, Metro Manila","orig":"An Act Declaring February 16 of Every Year As Caloocan City Day, A Special Nonworking Holiday in Caloocan City, Metro Manila"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7550","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7550_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6033-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"February 16 of every year is hereby declared as Caloocan City Day."}},{"id":"PH-H6033-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"February 16 of every year shall be a special nonworking holiday in Caloocan City, Metro Manila, and the city government and people therein are urged to celebrate the occasion with fitting ceremonies, activities and programs that are beneficial to all concerned."}},{"id":"PH-H6033-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring February 16 of Every Year As Caloocan City Day, A Special Nonworking Holiday in Caloocan City, Metro Manila","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6034"] = {"id":"PH-H6034","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7551_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布每年3月16日为“Araw Ng Davao”及达沃市特别非工作公共假日的法案","en":"An Act Declaring March 16 of Every Year As Araw Ng Davao, A Special Nonworking Public Holiday in Davao City","orig":"An Act Declaring March 16 of Every Year As Araw Ng Davao, A Special Nonworking Public Holiday in Davao City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7551","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7551_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6034-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In accordance with the approval of Commonwealth Act No. 51, otherwise known as the Charter of Davao City, mandating the creation of the city as a distinct political subdivision, this Act declares March 16 of 1990 and every year thereafter as Araw ng Davao, a special nonworking public holiday in the entire Davao City."}},{"id":"PH-H6034-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"On the anniversary day, March 16, the officials of Davao City shall lead appropriate and meaningful celebrations and activities participated in by officials and employees of the national government agencies or instrumentalities, civic, religious and nongovernment organizations, and private companies doing business and operating in Davao City in order to give significance and meaning to the occasion and to honor the inhabitants of Davao City.\nSection This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring March 16 of Every Year As Araw Ng Davao, A Special Nonworking Public Holiday in Davao City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6035"] = {"id":"PH-H6035","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7552_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"宣布每年5月7日为邦板牙省特别非工作假日的法案","en":"An Act Declaring May Seven of Every Year As A Special Nonworking Holiday in the Province of Pampanga","orig":"An Act Declaring May Seven of Every Year As A Special Nonworking Holiday in the Province of Pampanga"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7552","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-05-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7552_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6035-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"May Seven of every year is hereby declared as a special nonworking holiday in the Province of Pampanga."}},{"id":"PH-H6035-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p85","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring May Seven of Every Year As A Special Nonworking Holiday in the Province of Pampanga","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
